export function useSaveAutopilotProfile() {
  const qc = useQueryClient();
  const { success, error } = useMutationToast();
  return useMutation({
    mutationFn: (params: AutopilotProfile) =>
      request<AutopilotProfile>('/charge-autopilot/profile', {
        method: 'PUT',
        body: JSON.stringify(params),
      }),

export async function request<T>(path: string, options: ApiRequestOptions = {}): Promise<T> {
  const {
    responseType = 'json',
    skipAuthRefresh = false,
    acceptedStatuses = [],
    requiresLiveMode = false,
    headers,
    ...fetchOptions
  } = options

  assertOperationalWriteAllowed(fetchOptions.method, requiresLiveMode)

export function assertOperationalWriteAllowed(
  method: string | undefined,
  requiresLiveMode = false,
): void {
  const normalizedMethod = (method ?? 'GET').toUpperCase();
  if (READ_METHODS.has(normalizedMethod) || !requiresLiveMode) return;

  const snapshot = readOperationalModeFromEnvironment();
  if (snapshot.isReadOnly) {
    throw new OperationalModeWriteError(snapshot.mode);
  }

