513: func classifySeverity(signal string, zScore float64) string {
514: 	if criticalSignals[signal] && zScore > 4 {
515: 		return "critical"
516: 	}
517: 	if zScore > 5 {
518: 		return "critical"
519: 	}
520: 	if zScore > 4 || criticalSignals[signal] {
521: 		return "warning"
522: 	}
523: 	return "info"
524: }

